rows=[]
def add(i,url,title,pub,version,file,section,pop,limits,note,level='section'):
 p=Path(file);p=p if p.is_absolute() else C/p
 assert p.is_file(),p
 rows.append(dict(id=i,url=url,titre=title,editeur=pub,version_annee=version,date_consultation='2026-11-02',section_page=section,population=pop,limites=limits,cache_external=str(p),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),lecteur='sol_endocrinologie',read_level=level,passage_paraphrase=note))
add('S1','https://dam-api.bfs.admin.ch/hub/api/dam/assets/32686265/master','CIM-10-GM E35 et subdivisions astérisque','OFS Suisse','2024',R/'nosology/fragments/S05.json','Entrées locales E35*, E35.0*, E35.1*, E35.8*','Classification suisse','Libellés2024, sans certification du codage individuel2026.','Les manifestations thyroïdiennes, surrénaliennes et des autres glandes sont distinguées ; la catégorie ne décrit pas une maladie autonome.')
add('S2','https://klassifikationen.bfarm.de/icd-10-gm/kode-suche/htmlgm2024/block-e20-e35.htm','Inclusions E35* et catégories voisines','BfArM Allemagne','2024','/tmp/medina-source-cache/endocrinologie/E32/bfarm2024.html','E35.0/.1/.8 et notes ; réutilisation déclarée du cache lu ce jour puis nouvelle lecture E35','Classification allemande','Notes confrontées aux libellés suisses ; absence d’exemple en E35.8 n’est pas preuve que la rubrique soit vide.','Thyroïde tuberculeuse A18.8†/E35.0*, Addison tuberculeux A18.7†/E35.1*, Waterhouse-Friderichsen méningococcique A39.1†/E35.1*. Autres causes classées ailleurs ne reçoivent pas automatiquement ces paires.')
add('S3','https://www.bfarm.de/EN/Code-systems/Classifications/ICD/ICD-10-GM/Tabular-list/codestructure.html','Code structure : codes primaires et secondaires','BfArM Allemagne','Page consultée2novembre2026','bfarm-structure.html','Primary, additional and optional codes ; dagger/asterisk','Classification','Principe allemand, pas validation administrative suisse individuelle.','Astérisque ne s’utilise pas seul ; code étiologique primaire peut être associé. Une maladie classée ailleurs n’est pas forcément infectieuse : pas réduction de toute E35 aux seules inclusions infectieuses nommées.')
add('S4','https://www.rosenfluh.ch/media/paediatrie/2023/03/Nebenniereninsuffizienz.pdf','Nebenniereninsuffizienz : selten, aber potenziell lebensgefährlich','Christa E.Flück, Universitäts-Kinderklinik Bern, Pädiatrie','3/2023','fluck2023.pdf','p28 : normal et signes ; p30–33 : niveaux, diagnostic/traitement ; tableau2 p31','Enfants et adolescents, contexte suisse','Revue suisse pédiatrique ; exemples génétiques et auto-immuns ne deviennent pas E35. Tableau d’âge présente bornes qui se chevauchent à3/12ans, non harmonisé par invention. Légende figure3 attribuant CRH à hypophyse non reprise : texte situe correctement hypothalamus.','Cortex et médulla distincts ; aldostérone surtout régulée par rénine-angiotensine/électrolytes, pas uniquement axe corticotrope. Crise : traiter immédiatement, prélèvements sans retarder ; tableau25/50/100mg selon âge et stress glucocorticoïde, pas triplement automatique fludrocortisone. Seuil cortisol dépend contexte et méthode.')
add('S5','https://www.nice.org.uk/guidance/ng243/chapter/Recommendations','NG243 : Adrenal insufficiency, identification and management','NICE Royaume-Uni','2024','nice2024.html','1.2.7–13,1.3 remplacement ciblé,1.4 stress/grossesse,1.6–1.8 crise/suivi','≥16ans et parcours pédiatrique distingués','Guide britannique, pas FI suisse ni règle de remboursement. Doses chroniques fludrocortisone différentes de FI suisse ; non fusionnées.','Cortisol8–9h chez≥1an :<150suspect,150–300incertain,>300très improbable, seulement méthodes modernes et patient/contexte appropriés. Crise : hydrocortisone immédiate,100mg puis200mg/24h ou50mg4fois/j chez adulte très malade, remplissage et cause en parallèle ; sous16ans protocole pédiatrique. Remplacement non interrompu en grossesse.')
add('S6','https://pmc.ncbi.nlm.nih.gov/articles/PMC11180513/','ESE/Endocrine Society Joint Clinical Guideline : Glucocorticoid-induced adrenal insufficiency','Beuschlein (USZ Zürich) et coll., sociétés européenne/américaine','10mai2024','ese2024.xml','Section3 R3.1–3.2, tableaux8–9 et rationales','Surtout adultes exposés aux glucocorticoïdes, pas guideline spécifique d’infections glandulaires','Consensus conjoint, auteurs suisses/européens ; pas fondement américain seul, confronté à Flück/NICE/FI. Atteinte iatrogène discutée en différentiel, pas classée automatiquement E35.','Instabilité ou malabsorption impose parentéral ; crise clinique sans attendre confirmation. Schéma100mg puis200/24h est distinct des protocoles pédiatriques et des doses anti-inflammatoires. Inducteurs dont rifampicine peuvent précipiter une insuffisance. Pas fludrocortisone dans déficit central/iatrogène sans déficit minéralocorticoïde.')
add('S7','https://pmc.ncbi.nlm.nih.gov/articles/PMC10646833/','Emergency and perioperative management of adrenal insufficiency in children : BSPED consensus','Mushtaq et coll., Royaume-Uni','2023','/tmp/medina-source-cache/endocrinologie/E25/bsped.html','Tableau3 de crise réellement relu ce jour ; contexte/méthodes déjà lus lors E25','Enfants et adolescents, âge corrigé pour nouveau-nés','Réutilisation déclarée, pas lecture nouvelle du texte entier. Consensus européen à adapter au centre suisse et FI. Tableau comparatif des anciens guides n’est pas le tableau de conduite BSPED.','Options d’âge IM/IV25mg<1an,50mg1–5ans,100mg≥6ans ; ou poids IV2mg/kgmax100 après28jours corrigés,4mg/kg chez nouveau-né, puis fréquence/suivi selon état. Options non additionnées, pas100mg uniforme au nouveau-né. Glucocorticoïde de stress, pas hausse automatique fludrocortisone.')
add('S8','https://www.bag.admin.ch/dam/de/sd-web/nEBReGtQYlpu/6_2025%20BAG%20Bull_DE_postexpositionsproph%20Meningo.pdf','Vorgehen nach Kontakt mit invasiver Meningokokken-Erkrankung','OFSP/BAG Suisse, PIGS/SGGG','Bulletin4 du20janvier2025','ofsp-meningo2025.pdf','p12–16 : épidémiologie, contacts, déclaration, délais, figure3 et vaccination','Cas invasif possible/probable/confirmé et contacts suisses','Document2025 daté ; pas incidence actuelle E35. Schémas de prophylaxie pédiatrique/allaitement à confronter aux FI, qui diffèrent pour ciprofloxacine.','Hospitaliser/traiter sans attendre laboratoire ; déclaration suspicion dans24h. Contact étroit de7jours avant signes à24h après antibiothérapie ; prophylaxie idéalement24h et début au plus10jours après exposition, vaccination selon critères. Ciprofloxacine premier choix hors grossesse ; alternatives rifampicine/ceftriaxone. Simple proximité/classe scolaire pas automatiquement contact étroit.48cas/an0,6/100000moyenne décennale du document, pas fréquence Waterhouse.')
add('S9','https://www.bag.admin.ch/dam/fr/sd-web/fPW7HAdyOiZ0/tuberkulose-handbuch.pdf','Tuberculose en Suisse : guide professionnel','Ligue pulmonaire suisse/OFSP, sociétés suisses','V1.2024','swiss-tb.pdf','p9 épidémiologie ; passages diagnostic, chapitre7 traitement général ;p46déclaration','Tuberculose suisse générale, pas série endocrinienne','Source générale ; pas protocole spécifique thyroïde/surrénale ni donnée2026 actualisée.94%atteinte pulmonaire ne signifie pas6%de toutes atteintes extrapulmonaires exclusives.','2022 :365cas4,16/100000, non incidence E35. Prélèvements/microbiologie et sensibilité guident traitement combiné ; schéma standard daté2mois4agents puis4mois2agents, durées/cas particuliers spécialisés. Déclaration clinique sous semaine et laboratoire24h selon version, à distinguer méningococcie24h. Une thyroïde tuberculeuse n’hérite pas automatiquement d’un schéma court de TB pulmonaire.')
add('S10','https://pmc.ncbi.nlm.nih.gov/articles/PMC9999363/','Approach to the Patient With Adrenal Hemorrhage','Elhassan et coll., Birmingham/Londres Royaume-Uni','2023','hemorrhage2023.xml','Épidémiologie, Clinical relevance/presentation, Laboratory Investigations réellement lu, management aigu et suivi','Adultes avec hémorragie surrénalienne','Revue européenne en revue américaine, pas guideline américaine seule ; séries hétérogènes, seuils de suivi dépendants de méthode.','Hémorragie bilatérale à risque de déficit, unilatérale rarement insuffisante ; pigmentation peut manquer en aigu. Stabilisation, substitution et traitement cause ; conservation fréquente, embolisation si saignement persistant, chirurgie selon contexte tumoral et stabilité. Pas chirurgie automatique de toute hémorragie, récupération hormonale possible mais non garantie.')
add('S11','https://pmc.ncbi.nlm.nih.gov/articles/PMC9307021/','Adrenal trauma experience at a major tertiary centre in Sweden','Falhammar et coll., Karolinska Suède','2022','sweden2022.xml','Résumé et discussion/limites','1743traumatismes abdominaux graves2013–2018,29lésions surrénales','Rétrospective monocentrique ; aucun cortisol matinal/test de stimulation chez survivants. Pas preuve que toute hémorragie bilatérale garde sa fonction.','1,7%avec hémorragie dans cette population, surtout unilatérale ; pas signes cliniques de déficit observés au suivi, mais fonction hormonale non vérifiée systématiquement. Ce n’est ni incidence infectieuse suisse ni motif d’ignorer une crise.')
add('S12','https://pmc.ncbi.nlm.nih.gov/articles/PMC13030784/','Thyroid Tuberculosis Abscess : systematic review of diagnostic pathways and management','Shivashankar et coll., équipes australiennes','15mars2026','thyroid-tb2026.xml','Résultats3.1–3.7, discussion4.1–4.3, conclusions','22études,33cas publiés1990–2025','Cas/petites séries sans comparaison, données microbiologiques et pourcentages parfois incohérents ; pas précision de risque populationnel ni protocole suisse. Pas fondement américain.','Souvent masse cervicale et fonction thyroïdienne conservée,23/25euthyroïdes au bilan documenté ; image non spécifique. Cytologie plus culture/amplification utiles ; histologie/BAAR seuls ne confirment pas espèce, confirmation complexe tuberculeux limitée. Traitement étiologique et drainage/chirurgie selon compression/incertitude, pas thyroïdectomie systématique.')
add('S13','https://pmc.ncbi.nlm.nih.gov/articles/PMC12577612/','Thyroid Tuberculosis Misdiagnosed as Papillary Thyroid Carcinoma','Tong et coll., Chine','2025','tbthyroid2025.xml','Présentation, histologie et limites du cas ; discussion regardée mais traitement général non adopté','Une femme67ans','Microbiologie spécifique non documentée dans texte lu ; diagnostic rapporté surtout histologique. Fréquence0,1–0,4%et stratégie courte américaine non adoptées. Figures NC non réutilisées.','Nodule suspect et fonction thyroïdienne normale peuvent révéler une inflammation granulomateuse ; prélèvement limité peut induire diagnostic erroné. Ce cas illustre un différentiel, pas une preuve de spécificité histologique ni un taux de cancer.')
for i,k,pmid,version,pop,limit,note in [
('S14','infect-adrenal2026','42852841','9octobre2026','Revue internationale sur infections surrénaliennes','Résumé seul ; aucun algorithme ou dose fondé uniquement dessus ;14–100%très hétérogène non utilisé comme risque individuel.','Tuberculose/histoplasmose et autres agents peuvent léser les glandes ; cause et réserve hormonale sont évaluées en parallèle, y compris suivi si réserve initiale conservée.'),
('S15','waterhouse2026','42665693','29août2026','65études,86cas mortels confirmés à autopsie, Italie','Résumé seul, sélection de décès : pas dénominateur pour létalité, pas test clinique prospectif.','Aspect hémorragique bilatéral dans contexte septique avec agents divers ; source décrit méthode d’autopsie et limites microbiologiques, pas seul méningocoque ni taux de mortalité de tous malades.')]:
 a=json.loads((C/(k+'-meta.json')).read_text())['resultList']['result'][0]
 add(i,'https://pubmed.ncbi.nlm.nih.gov/'+pmid+'/',a['title'],a.get('authorString','Auteurs publiés'),version,k+'-meta.json','Résumé publié',pop,limit,note,'abstract')
for i,name,gtin,version,file,pop,note,limits in [
('S16','Solu-Cortef injectable100/250mg','7680235330016','Octobre2025','solucortef.html','Insuffisance surrénale et indications multiples, IV/IM','Urgence IV préférée ;100mg en au moins30secondes, perfusion selon tableau clinique. Pédiatrie ajustée à état, mention minimum25mg/j non bolus universel ; voies intrathécale/épidurale non celles de la crise. Rifampicine accélère métabolisme ; grossesse nécessité absolue, rein sans adaptation.','FI générale multindications non protocole complet d’urgences ; schémas NICE/BSPED identifiés séparément.'),
('S17','Hydrocortisone Galepharm comprimé10mg sécable','7680579700018','Août2025','/tmp/medina-source-cache/endocrinologie/E25/galepharm.txt','Remplacement oral chronique','Insuffisance chronique10–20mg/j parfois davantage, prises selon indication ; urgence parentérale si absorption insuffisante. Dose hyperplasie10–30mg/j n’est pas dose E35 universelle.','Réutilisation déclarée du cache lu E25, nouvelle lecture posologie chronique ;15–25mgdu guide britannique non substitué comme dose de FI. Swisspeddose annexée non confondue avec FI.'),
('S18','Florinef comprimé0,1mg','7680310950184','Mars2026','florinef.html','Déficit minéralocorticoïde prouvé','Adulte0,1mg3fois/semaine à0,2mg/j, standard0,1 ;12–18comme adulte ;0–12ans2–5µg/kg/j. Suivi pression/électrolytes/rénine, rein/foie peu étudiés ; grossesse nécessité, pas allaiter selon FI.','Repères différents de NICE et revue pédiatrique, pas dose composite ni triplement automatique au stress ; urgence par hydrocortisone de stress distincte.'),
('S19','Rocephin ceftriaxone IV/IM','7680446250011','Juin2025','rocephin.html','Malade infecté, et prophylaxie OFSP distinguée','Adulte>12ans1–2g/j, jusqu4g/j en sévère ; méningite enfant100mg/kg/jmax4g ; nouveau-né≤14jours20–50mg/kg/jmax50 ;15jours–12ans20–80mg/kg/j hors schéma spécifique, dose adulte si≥50kg ; prématuré jusqu’à41semaines postmenstruelles/calciumIV≤28jours contre-indiqués et hyperbilirubinémie non traiter. FormeIMlidocaïne jamaisIV.','La dose de prophylaxie125/250mgIM OFSP n’est pas celle d’une infection invasive, ni indication propre énumérée par cette FI ; protocole hospitalier et sourceSSI datés séparés.'),
('S20','Rimactan rifampicine gélules150/300mg','7680342790123','Octobre2023','rimactan.html','Traitement TB combiné et contacts méningocoque','Prophylaxie : adulte/adolescent>12ans et>60kg600mgq12h2jours ;≥1mois jusqu12ans ou ado<60kg10mg/kgq12hmaxadulte ;<1mois5mg/kgq12h2jours. Pas traitement de méningite manifeste. Contre-indication clairance<25ml/min et foie sévère ; induction/interactions majeures.','Bornes de poids exactes FI ne définissent pas le cas60kg ; OFSPprésente10mg/kgmax600≥1mois. Pas rifampicine seule pour TB ; forme adaptée jeune enfant, pas gélule imposée.'),
('S21','Ciproxine comprimés/suspension orale, pas Ciproxin HC otique','7680477950447','Août2025','ciproxine.html','Prophylaxie invasive adulte et protocole OFSP pédiatrique distinct','FI adulte500mgdoseunique pour prévention méningocoque. OFSP2025premier choix20mg/kgdoseunique, max500dès1mois ; données/indications pédiatriques FI ne couvrent pas ce schéma. FIcontre-indique grossesse/allaitement et croissance sauf exceptions, tizanidine/agomélatine ; tendons/neuropathie et corticoïdes, cations diminuent absorption.','Divergence réelle : OFSPautorise toutes molécules citées pendant allaitement, FIcipro interdit ; ne pas fusionner. Swisspeddose ajoutée au bas de page n’est pas le texte FI. HC otique homonyme exclu.')]:
 add(i,'https://amiko.oddb.org/fr/fi?gtin='+gtin,'Information professionnelle suisse '+name,'Swissmedic/AIPS via AmiKo',version,file,'Formulation, indication, posologie, contre-indications, adaptations ; précautions/interactions et grossesse ciblées',pop,limits,note)
add('S22','https://ssi.guidelines.ch/api/reader/get/glFile/10635','SSI Guidelines Meningitis : Swiss Addendum','Swiss Society for Infectious Diseases','PDFcréé/modifié28décembre2017','ssi-meningitis.pdf','Deux pages, traitement empirique et contraintes PL ; ceftriaxone, corticothérapie','Méningite bactérienne, selon rubriques','Addendum ancien, pas version dynamique2026 établie. Source découverte dans dossier G03 en lecture seule ; texte effectivement téléchargé et lu par nous, aucune reprise de validation étrangère.','Traitement empirique hospitalier suisse ceftriaxone2×2g ; doses enfants100mg/kg/j en1–2prises ; pas petite dose PEP. Choc/signes neurologiques changent décision de PL. Corticothérapie adjuvante méningite distincte du remplacement de crise, pas double schéma automatique.')
add('S23','https://openstax.org/books/anatomy-and-physiology-2e/pages/17-6-the-adrenal-glands','The adrenal glands','OpenStax','2e, version servie2026','openstax-adrenal.html','Anatomie/cortex/zones, hormones et rétrocontrôle','Science normale','Manuel américain de normal uniquement ; raccourcis ACTH/aldostérone et tumeur hypophysaire sécrétant cortisol non adoptés, confrontés à source suisse. Licence de figure historique propre2013, pas déduite du site actuel.','Capsule, cortex glomérulé/fasciculé/réticulé et médulla distincts ; stéroïdes corticosurrénaliens, catécholamines médullaires. Aldostérone surtout rénine-angiotensine et potassium selon Flück, pas simple dépendance corticotrope.')
add('S24','https://smifk-cims.ch/download_file/view/c28daec4-78b0-4a6e-a198-00ca757191fc/261','PROFILES2017','CIMS Suisse','2017','/workspace/medina-source-cache/C85/profiles2017-official.pdf','p22EPA6.4–6.9 et6a–6k ; SSP88 et214 repérés, nouvelle lecture ciblée','Formation suisse','Rapprochement pédagogique, pas mapping officiel CIM-E35 ni question fédérale garantie.','Choc/hypotension, méningisme, altération de conscience, douleur abdominale et purpura sont des portes d’entrée ; reconnaître décompensation et transmettre informations, pas reconnaître seulement un code.')
add('S25','https://openstax.org/books/anatomy-and-physiology-2e/pages/17-4-the-thyroid-gland','The thyroid gland','OpenStax','2e, version servie2026','openstax-thyroid.html','Anatomie, follicule/colloïde, hormones iodées et rétrocontrôle','Science normale','Manuel américain, pas fondation de conduite clinique. Pas reprise des généralités étiologiques sur hyperthyroïdie ou des détails simplificateurs de transport membranaire ; TH évité car homonyme du glossaire.','Follicules épithéliaux entourent colloïde/thyroglobuline, hormones iodées et stimulation hypophysaire ; structure, sécrétion et fonction ne sont pas équivalentes, une thyroïde infectée peut encore fonctionner.')
